@scope (#chapter-positional-encoding){.pm-chapter-section { --ink: #2d3748; --muted: #718096; --accent: #2C5282; --warm: #DD6B20; --line: #e2e8f0; --paper: #f7fafc; font-family: system-ui, -apple-system, sans-serif; color: var(--ink); background: var(--paper); padding: 24px; line-height: 1.6; font-size: 16px; box-sizing: border-box; }
.pm-chapter-section * { box-sizing: border-box; }
.pm-section-header { margin-bottom: 24px; border-bottom: 2px solid var(--accent); padding-bottom: 12px; }
.pm-section-title { font-size: 24px; font-weight: 700; margin: 0 0 8px 0; color: var(--accent); }
.pm-section-summary { font-size: 16px; color: var(--muted); margin: 0; }
.pm-content-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; margin-bottom: 32px; }
@media (max-width: 768px) { .pm-content-grid { grid-template-columns: 1fr; } }
.pm-paragraph { font-size: 16px; margin-bottom: 16px; text-align: justify; }
.pm-source-btn { display: inline-block; background: #edf2f7; border: 1px solid var(--line); color: var(--accent); padding: 4px 8px; font-size: 13px; border-radius: 4px; cursor: pointer; margin-left: 8px; vertical-align: middle; }
.pm-source-btn:hover { background: #e2e8f0; }
.pm-formula-box { background: #fff; border: 1px solid var(--line); padding: 16px; margin: 16px 0; border-radius: 6px; }
.pm-formula { font-family: 'Times New Roman', serif; font-size: 18px; text-align: center; margin: 8px 0; color: var(--ink); }
.pm-formula-note { font-size: 14px; color: var(--muted); text-align: center; margin-top: 8px; }
.pm-visual-workbench { background: #fff; border: 1px solid var(--line); border-radius: 8px; padding: 16px; }
.pm-viz-title { font-size: 18px; font-weight: 600; margin: 0 0 8px 0; color: var(--accent); }
.pm-viz-caption { font-size: 13px; color: var(--muted); margin-bottom: 16px; }
