.pm-chart-legend { font-size: 0.8rem; color: var(--muted); text-align: center; margin-top: 0.5rem; }
.pm-analysis-text { font-size: 0.95rem; line-height: 1.6; color: var(--ink); background: #fff; padding: 1rem; border-left: 3px solid var(--warm); }
.pm-comparison-grid { display: grid; grid-template-columns: 1.5fr 1fr; gap: 2rem; margin-top: 2rem; }
