.pm-data-table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
.pm-data-table th, .pm-data-table td { padding: 0.75rem; text-align: left; border-bottom: 1px solid var(--line); }
.pm-data-table th { background: var(--paper); font-weight: 600; color: var(--ink); }
.pm-data-table tr.highlight { background: rgba(44, 82, 130, 0.05); font-weight: 600; }
.pm-table-note { font-size: 0.8rem; color: var(--muted); margin-top: 0.5rem; font-style: italic; }
.pm-insight-panel { background: #fff; padding: 1.5rem; border: 1px solid var(--line); border-radius: 4px; }
.pm-insight-panel h3 { margin-top: 0; font-size: 1.1rem; color: var(--accent); }
.pm-list { padding-left: 1.2rem; }
.pm-list li { margin-bottom: 0.8rem; line-height: 1.5; color: var(--ink); }
@media (max-width: 768px) { .pm-workbench, .pm-comparison-grid { grid-template-columns: 1fr; } .pm-metric-cards { grid-template-columns: 1fr; } }
