    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const padding = 40;
    const chartHeight = canvas.height - padding * 2;
    const chartWidth = canvas.width - padding * 2;
    const maxVal = 30; // Scale for BLEU
    const barWidth = 60;

    // Draw Base Line
    const baseY = padding + chartHeight - (baseBLEU / maxVal) * chartHeight;
    ctx.beginPath();
    ctx.moveTo(padding, baseY);
    ctx.lineTo(padding + chartWidth, baseY);
    ctx.strokeStyle = '#e2e8f0';
    ctx.setLineDash([5, 5]);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#718096';
    ctx.font = '12px sans-serif';
    ctx.fillText(`Base: ${baseBLEU}`, padding + chartWidth - 60, baseY - 5);

    // Draw Current Bar
    const currentY = padding + chartHeight - (currentBLEU / maxVal) * chartHeight;
    const barHeight = chartHeight - (currentY - padding);

    ctx.fillStyle = '#2C5282';
    ctx.fillRect(padding + 20, currentY, barWidth, barHeight);

    // Label
    ctx.fillStyle = '#1a202c';
    ctx.fillText(currentBLEU.toFixed(1), padding + 20 + barWidth/2 - 10, currentY - 5);
    ctx.fillText('Current', padding + 20, canvas.height - 10);
  }

  function updateAblation() {
    const row = getRowData(configSelect.value);
    const bleu = parseFloat(row.values['BLEU (dev)']);
    const ppl = parseFloat(row.values['PPL (dev)']);
    const params = row.values['params ×10^6'];

    bleuEl.textContent = bleu.toFixed(1);
    pplEl.textContent = ppl.toFixed(2);
    paramsEl.textContent = params || 'N/A';

    // Analysis Text Generation based on claims
    let text = '';
    if (row.id.startsWith('A')) {
      const h = row.values['h'];
      if (h === '1') text = `单头注意力 (h=1) 导致 BLEU 下降 0.9 点 (24.9 vs 25.8)。这表明多头机制能有效捕捉不同子空间的信息，单头平均化抑制了这种能力。`;
      else if (h === '32') text = `头数过多 (h=32) 并未带来提升 (25.4)，且单头维度变小可能损害兼容性计算。`;
      else text = `在计算量恒定条件下，${h} 头配置表现${bleu >= baseBLEU ? '相当' : '稍弱'}。`;
    } else if (row.id.startsWith('B')) {
      text = `减小键维度 dk 至 ${row.values['d_k']} 损害了模型质量 (BLEU ${bleu})。说明点积兼容性函数对维度敏感，需要足够的容量来捕捉复杂关系。`;
    } else if (row.id.startsWith('C')) {
      if (row.values['N']) text = `层数 N=${row.values['N']} 显著影响性能。深层网络 (N=8 或 d_model=1024) 表现更好，证实了模型容量的重要性。`;
      else text = `调整 d_ff 影响前馈网络容量，d_ff=4096 时 BLEU 达到 26.2，优于基准。`;
    } else if (row.id.startsWith('D')) {
      if (row.values['P_drop'] === '0.0') text = `移除 Dropout (P=0.0) 导致 BLEU 大幅下降至 24.6，证明正则化对防止过拟合至关重要。`;
      else text = `调整 Dropout 或 Label Smoothing 对模型不确定性有直接影响。`;
    } else if (row.id === 'E') {
      text = `使用学习位置编码替代正弦编码，结果 (25.7) 与基准 (25.8) 几乎一致，说明位置注入方式具有灵活性。`;
    } else if (row.id === 'big') {
      text = `大模型 (d_model=1024, h=16) 在更多数据 (300K steps) 下训练，BLEU 提升至 26.4，证实了规模效应。`;
    }
    analysisEl.textContent = '原文报告行：'+row.label+'。BLEU(dev)='+bleu.toFixed(1)+'，PPL(dev)='+ppl.toFixed(2)+'；相对base的BLEU变化为'+(bleu-baseBLEU).toFixed(1)+'。仅适用于英德 newstest2013 开发集，不能据此预测任意联合配置，也不等同于newstest2014测试集结果。';
    document.getElementById('ablation-result').setAttribute('data-values',JSON.stringify([bleu,ppl]));
    drawChart(bleu);
  }

  configSelect.addEventListener('change', updateAblation);
  updateAblation(); // Init

  // Parsing Logic
  const tbody = document.getElementById('parsing-tbody');
  if (table4 && table4.rows) {
    table4.rows.forEach((row, idx) => {
      const tr = document.createElement('tr');
      const isTransformer = row.values['Parser'].includes('Transformer');
      if (isTransformer) tr.classList.add('highlight');

      tr.innerHTML = `
        <td>${row.values['Parser']}</td>
        <td>${row.values['Training']}</td>
        <td>${row.values['WSJ 23 F1']}</td>
      `;
      tbody.appendChild(tr);
    });
  }

  // Source Buttons
  document.querySelectorAll('.pm-btn-source').forEach(btn => {
    btn.addEventListener('click', (e) => {
      // Host handles data-source attribute
      const event = new CustomEvent('paperMind:source', { 
        detail: { sourceId: btn.dataset.source }, 
        bubbles: true 
      });
      btn.dispatchEvent(event);
    });
  });
})();})(d);})();
